solution.code:
import csv, io


def muat(teks):
    return list(csv.DictReader(io.StringIO(teks)))


def bersihkan(baris):
    terlihat, hasil = set(), []
    for r in baris:
        try:
            jumlah, harga = int(r["jumlah"]), int(r["harga"])
        except ValueError:
            continue
        kode = r["kode"].strip().upper()
        kunci = (r["tanggal"], kode, jumlah, harga)
        if kunci in terlihat:
            continue
        terlihat.add(kunci)
        hasil.append({"tanggal": r["tanggal"], "kode": kode, "jumlah": jumlah, "harga": harga})
    return hasil


def gabung(baris, produk):
    info = {p["kode"]: p for p in produk}
    hasil = []
    for r in baris:
        p = info.get(r["kode"], {})
        hasil.append({**r, "nama": p.get("nama", "Tidak dikenal"), "kategori": p.get("kategori", "Lainnya")})
    return hasil


def total_per(baris, kunci):
    hasil = {}
    for r in baris:
        hasil[r[kunci]] = hasil.get(r[kunci], 0) + r["jumlah"] * r["harga"]
    return hasil


def laporan(baris):
    pendapatan = sum(r["jumlah"] * r["harga"] for r in baris)
    unit = {}
    for r in baris:
        unit[r["nama"]] = unit.get(r["nama"], 0) + r["jumlah"]
    return {
        "pendapatan": pendapatan,
        "terlaris": max(unit, key=unit.get),
        "per_kategori": total_per(baris, "kategori"),
        "rata_transaksi": round(pendapatan / len(baris)),
    }


bersih = bersihkan(muat(DATA))
gab = gabung(bersih, muat(PRODUK))
print(laporan(gab))

