solution.code:
def batang(data, lebar=20):
    terbesar = max(data.values(), default=0)
    if terbesar == 0:
        return {k: "" for k in data}
    return {k: "#" * round(v / terbesar * lebar) for k, v in data.items()}


print(batang({"Kopi": 10, "Teh": 3, "Roti": 5, "Susu": 2}))

